-- Phase 2: additive shadow ledger. No existing tables/functions/read paths change.
create table operations_private.hub_baseline_versions (
 id uuid primary key default gen_random_uuid(),
 source text not null check(source in ('smartstore','makeshop','ably')),
 version integer not null check(version>0),
 previous_version_id uuid,
 source_snapshot_id uuid references public.seller_inventory_snapshots(snapshot_id),
 export_job_id uuid references public.operations_hub_export_jobs(job_id),
 request_id uuid not null unique,
 event text not null check(event in ('initial_seed','confirmed_plan','restore')),
 operation_count integer not null check(operation_count>=0),
 confirmed_at timestamptz,
 created_at timestamptz not null default clock_timestamp(),
 created_by text not null,
 unique(source,version),unique(source,id),
 foreign key(source,previous_version_id) references operations_private.hub_baseline_versions(source,id),
 check((version=1 and previous_version_id is null and event='initial_seed' and source_snapshot_id is not null)
  or (version>1 and previous_version_id is not null and event<>'initial_seed'))
);
create table operations_private.hub_baseline_rows (
 version_id uuid not null references operations_private.hub_baseline_versions(id),
 product_code text not null check(length(btrim(product_code)) between 1 and 128 and product_code=btrim(product_code)),
 option_code text not null default '' check(length(option_code)<=128 and option_code=btrim(option_code)),
 facts jsonb not null check(jsonb_typeof(facts)='object' and pg_column_size(facts)<=16384),
 source_row_no integer,
 source_file_name text,
 primary key(version_id,product_code,option_code)
);
create table operations_private.hub_baseline_heads (
 source text primary key,
 current_version_id uuid not null,
 mode text not null default 'shadow' check(mode='shadow'),
 foreign key(source,current_version_id) references operations_private.hub_baseline_versions(source,id)
);
create table operations_private.hub_transformation_plans (
 id uuid primary key default gen_random_uuid(),
 source text not null,
 baseline_version_id uuid not null,
 request_id uuid not null unique,
 operations jsonb not null check(jsonb_typeof(operations)='array' and jsonb_array_length(operations)<=50000 and pg_column_size(operations)<=16777216),
 artifact_sha256 text check(artifact_sha256 is null or artifact_sha256 ~ '^[0-9a-f]{64}$'),
 mode text not null default 'shadow' check(mode='shadow'),
 created_at timestamptz not null default clock_timestamp(),
 created_by text not null,
 foreign key(source,baseline_version_id) references operations_private.hub_baseline_versions(source,id)
);
create index hub_transformation_plans_baseline_idx on operations_private.hub_transformation_plans(baseline_version_id);
create index hub_baseline_versions_snapshot_idx on operations_private.hub_baseline_versions(source_snapshot_id);
create index hub_baseline_versions_previous_idx on operations_private.hub_baseline_versions(previous_version_id);
create index hub_baseline_versions_export_job_idx on operations_private.hub_baseline_versions(export_job_id);
create table operations_private.hub_source_deltas (
 request_id uuid primary key,
 source text not null check(source in ('sellpia','smartstore','makeshop','ably')),
 previous_snapshot_id uuid,
 snapshot_id uuid,
 identity text not null check(length(btrim(identity)) between 1 and 512),
 before_values jsonb,
 after_values jsonb,
 changed_fields jsonb not null check(jsonb_typeof(changed_fields)='array' and jsonb_array_length(changed_fields)>0),
 rule_impact jsonb not null check(jsonb_typeof(rule_impact)='object'),
 created_at timestamptz not null default clock_timestamp(),
 check(before_values is distinct from after_values)
);
create index hub_source_deltas_snapshot_idx on operations_private.hub_source_deltas(source,snapshot_id);

alter table operations_private.hub_baseline_versions enable row level security;
alter table operations_private.hub_baseline_rows enable row level security;
alter table operations_private.hub_baseline_heads enable row level security;
alter table operations_private.hub_transformation_plans enable row level security;
alter table operations_private.hub_source_deltas enable row level security;
revoke all on operations_private.hub_baseline_versions,operations_private.hub_baseline_rows,
 operations_private.hub_baseline_heads,operations_private.hub_transformation_plans,operations_private.hub_source_deltas from public,anon,authenticated;

create function operations_private.hub_shadow_immutable_v1()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin raise exception 'Shadow ledger is append-only; use a forward version or scoped rollback transaction.'; end $$;
revoke all on function operations_private.hub_shadow_immutable_v1() from public,anon,authenticated;
create trigger hub_baseline_versions_immutable before update or delete on operations_private.hub_baseline_versions for each row execute function operations_private.hub_shadow_immutable_v1();
create trigger hub_baseline_rows_immutable before update or delete on operations_private.hub_baseline_rows for each row execute function operations_private.hub_shadow_immutable_v1();
create trigger hub_transformation_plans_immutable before update or delete on operations_private.hub_transformation_plans for each row execute function operations_private.hub_shadow_immutable_v1();
create trigger hub_source_deltas_immutable before update or delete on operations_private.hub_source_deltas for each row execute function operations_private.hub_shadow_immutable_v1();

-- Initial seed is management-only, and copies operational reference facts, not Rule values.
create function operations_private.hub_baseline_shadow_seed_v1(p_source text,p_request_id uuid)
returns jsonb language plpgsql set search_path=pg_catalog set statement_timeout='60s' set lock_timeout='5s' as $$
declare existing operations_private.hub_baseline_versions%rowtype; sid uuid; vid uuid; rows_count integer;
begin
 if p_source not in ('smartstore','makeshop','ably') or p_source is null or p_request_id is null then raise exception 'source and request_id required';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-baseline-shadow:'||p_source,0));
 select * into existing from operations_private.hub_baseline_versions where request_id=p_request_id;
 if found then
  if existing.source<>p_source or existing.event<>'initial_seed' then raise exception 'seed request_id reused with different inputs';end if;
  return jsonb_build_object('version_id',existing.id,'version',existing.version,'source',p_source,'reused',true);
 end if;
 if exists(select 1 from operations_private.hub_baseline_heads where source=p_source) then raise exception 'shadow head already seeded';end if;
 select snapshot_id into sid from public.seller_inventory_snapshots where source_channel=p_source and upload_status='ready'
  order by coalesce(completed_at,created_at) desc,created_at desc,snapshot_id desc limit 1;
 if sid is null then raise exception 'ready seller reference not found';end if;
 if not exists(select 1 from public.seller_inventory_snapshot_rows where snapshot_id=sid) then raise exception 'empty seed snapshot';end if;
 insert into operations_private.hub_baseline_versions(source,version,source_snapshot_id,request_id,event,operation_count,created_by)
 values(p_source,1,sid,p_request_id,'initial_seed',0,current_user) returning id into vid;
 insert into operations_private.hub_baseline_rows(version_id,product_code,option_code,facts,source_row_no,source_file_name)
 select vid,product_code,coalesce(option_code,''),jsonb_build_object('stock',stock,'price',jsonb_build_object(
  'base',base_price,'discounted',discounted_base_price,'option',option_price,'final',final_price,'terms',coalesce(discount_terms,'[]'::jsonb))),
  source_row_no,raw_payload->>'source_file_name'
 from public.seller_inventory_snapshot_rows where snapshot_id=sid;
 get diagnostics rows_count=row_count;
 insert into operations_private.hub_baseline_heads(source,current_version_id) values(p_source,vid);
 return jsonb_build_object('source',p_source,'version_id',vid,'version',1,'snapshot_id',sid,'row_count',rows_count,'reused',false);
end $$;
revoke all on function operations_private.hub_baseline_shadow_seed_v1(text,uuid) from public,anon,authenticated;

-- Persist exactly the operations tested by a shadow serializer; this is NOT upload confirmation.
create function operations_private.hub_shadow_plan_save_v1(p_source text,p_version_id uuid,p_request_id uuid,p_operations jsonb,p_artifact_sha256 text default null)
returns uuid language plpgsql set search_path=pg_catalog set lock_timeout='5s' as $$
declare existing operations_private.hub_transformation_plans%rowtype; op jsonb; original jsonb; after_value jsonb; result_id uuid; k text;
begin
 if p_source is null or p_version_id is null or p_request_id is null or jsonb_typeof(p_operations) is distinct from 'array' or jsonb_array_length(p_operations)>50000 or pg_column_size(p_operations)>16777216 then raise exception 'invalid plan';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-shadow-plan:'||p_request_id::text,0));
 select * into existing from operations_private.hub_transformation_plans where request_id=p_request_id;
 if found then
  if (existing.source,existing.baseline_version_id,existing.operations,existing.artifact_sha256) is distinct from (p_source,p_version_id,p_operations,p_artifact_sha256) then raise exception 'plan request_id reused with different inputs';end if;
  return existing.id;
 end if;
 if not exists(select 1 from operations_private.hub_baseline_heads where source=p_source and current_version_id=p_version_id and mode='shadow') then raise exception 'expected shadow baseline version changed';end if;
 if exists(select 1 from jsonb_array_elements(p_operations) x group by x->>'seller_product_code',coalesce(x->>'seller_option_code',''),x->>'field_key' having count(*)>1) then raise exception 'duplicate operation identity/field';end if;
 for op in select value from jsonb_array_elements(p_operations) loop
  if jsonb_typeof(op) is distinct from 'object' or op->>'source_channel' is distinct from p_source
   or coalesce(op->>'field_key','') not in ('sellpia_sale_price','sellpia_current_stock')
   or coalesce(op->>'provenance','') not in ('manual','calculated','preserve_shared') then raise exception 'unsupported operation';end if;
  select facts into original from operations_private.hub_baseline_rows where version_id=p_version_id
   and product_code=op->>'seller_product_code' and option_code=coalesce(op->>'seller_option_code','');
  if not found then raise exception 'operation identity missing from baseline';end if;
  original:=case when op->>'field_key'='sellpia_sale_price' then original->'price' else original->'stock' end;
  after_value:=op->'after';
  if not op?'before' or not op?'after' or original is distinct from op->'before' then raise exception 'operation before value mismatch';end if;
  if op->>'field_key'='sellpia_current_stock' then
   if jsonb_typeof(after_value) is distinct from 'number' then raise exception 'stock must be an integer';end if;
   if (after_value::text)::numeric<0 or (after_value::text)::numeric<>trunc((after_value::text)::numeric) or (after_value::text)::numeric>9007199254740991 then raise exception 'stock out of range';end if;
  else
   if jsonb_typeof(after_value) is distinct from 'object' or jsonb_typeof(after_value->'terms') is distinct from 'array' or jsonb_array_length(after_value->'terms')>16 then raise exception 'price tuple/terms invalid';end if;
   foreach k in array array['base','discounted','option','final'] loop
    if jsonb_typeof(after_value->k) is distinct from 'number' then raise exception 'price component missing';end if;
    if (after_value->>k)::numeric<>trunc((after_value->>k)::numeric) or abs((after_value->>k)::numeric)>9007199254740991 or (k<>'option' and (after_value->>k)::numeric<0) then raise exception 'price component out of range';end if;
   end loop;
   if (after_value->>'discounted')::numeric+(after_value->>'option')::numeric<>(after_value->>'final')::numeric then raise exception 'inconsistent final price';end if;
  end if;
 end loop;
 insert into operations_private.hub_transformation_plans(source,baseline_version_id,request_id,operations,artifact_sha256,created_by)
 values(p_source,p_version_id,p_request_id,p_operations,p_artifact_sha256,current_user) returning id into result_id;
 return result_id;
end $$;
revoke all on function operations_private.hub_shadow_plan_save_v1(text,uuid,uuid,jsonb,text) from public,anon,authenticated;

-- Only this bounded read is API-accessible. Custom operator sessions match the existing Hub auth contract.
create function operations_private.hub_baseline_shadow_read_v1(p_session_token text,p_source text,p_identities jsonb)
returns jsonb language plpgsql security definer stable set search_path=pg_catalog set statement_timeout='15s' as $$
declare vid uuid; sid uuid; result_rows jsonb;
begin
 perform operations_private.require_operations_hub_operator_session(p_session_token);
 if p_source is null or p_source not in ('smartstore','makeshop','ably') or jsonb_typeof(p_identities) is distinct from 'array' or jsonb_array_length(p_identities) not between 1 and 500 then raise exception 'shadow read requires 1..500 identities';end if;
 if exists(select 1 from jsonb_array_elements(p_identities) x where jsonb_typeof(x) is distinct from 'object' or length(btrim(coalesce(x->>'product_code',''))) not between 1 and 128 or length(coalesce(x->>'option_code',''))>128) then raise exception 'invalid identity';end if;
 select current_version_id into vid from operations_private.hub_baseline_heads where source=p_source and mode='shadow';
 if vid is null then raise exception 'shadow baseline not seeded';end if;
 select snapshot_id into sid from public.seller_inventory_snapshots where source_channel=p_source and upload_status='ready'
  order by coalesce(completed_at,created_at) desc,created_at desc,snapshot_id desc limit 1;
 with identities as(select distinct btrim(x->>'product_code') product_code,btrim(coalesce(x->>'option_code','')) option_code from jsonb_array_elements(p_identities) x)
 select coalesce(jsonb_agg(jsonb_build_object('product_code',i.product_code,'option_code',i.option_code,
  'baseline',b.facts,'snapshot',case when r.product_code is null then null else jsonb_build_object('stock',r.stock,'price',jsonb_build_object(
  'base',r.base_price,'discounted',r.discounted_base_price,'option',r.option_price,'final',r.final_price,'terms',coalesce(r.discount_terms,'[]'::jsonb))) end,
  'source_row_no',b.source_row_no,'source_file_name',b.source_file_name) order by i.product_code,i.option_code),'[]'::jsonb) into result_rows
 from identities i left join operations_private.hub_baseline_rows b on b.version_id=vid and b.product_code=i.product_code and b.option_code=i.option_code
 left join public.seller_inventory_snapshot_rows r on r.snapshot_id=sid and r.product_code=i.product_code and coalesce(r.option_code,'')=i.option_code;
 return jsonb_build_object('source',p_source,'mode','shadow','version_id',vid,'snapshot_id',sid,'rows',result_rows);
end $$;
revoke all on function operations_private.hub_baseline_shadow_read_v1(text,text,jsonb) from public;
grant execute on function operations_private.hub_baseline_shadow_read_v1(text,text,jsonb) to anon,authenticated;
create function public.hub_baseline_shadow_read_v1(p_session_token text,p_source text,p_identities jsonb)
returns jsonb language sql security invoker stable set search_path=pg_catalog as $$
 select operations_private.hub_baseline_shadow_read_v1(p_session_token,p_source,p_identities);
$$;
revoke all on function public.hub_baseline_shadow_read_v1(text,text,jsonb) from public;
grant execute on function public.hub_baseline_shadow_read_v1(text,text,jsonb) to anon,authenticated;
notify pgrst,'reload schema';
